#include <stdio.h>
int max(int a, int b) {
    int result;
    __asm__ (
        "cmpl %2, %1\n"
        "jg .Lthen\n"
        "movl %2, %0\n"
        "jmp .Ldone\n"
        ".Lthen:\n"
        "movl %1, %0\n"
        ".Ldone:\n"
        : "=r"(result)
        : "r"(a), "r"(b)
    );
    return result;
}
