// Simple bit manipulation using inline assembly
static int __attribute__((noinline)) popcount(int x) {
    int result = 0;
    while (x) {
        result += (x & 1);
        x >>= 1;
    }
    return result;
}
int main() {
    printf("popcount(0xFF)=%d\n", popcount(0xFF));
    printf("popcount(0xF0)=%d\n", popcount(0xF0));
    printf("popcount(0)=%d\n", popcount(0));
    return 0;
}

